// GcbOf returns the Grapheme_Cluster_Break class of cp, GcbOther
// when no range covers it — the default
// GraphemeBreakProperty.txt's own @missing: 0000..10FFFF; Other
// header declares.
//
// The ranges are sorted by lower bound and disjoint, so the covering
// range is unique and a binary search finds it.
func GcbOf(cp uint32) Gcb {
	lo, hi := 0, len(gcbRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := gcbRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return entry.class
		}
	}
	return GcbOther
}

// IncbOf returns the Indic_Conjunct_Break class of cp, IncbNone
// when no range covers it — the default
// DerivedCoreProperties.txt's own @missing: 0000..10FFFF; InCB;
// None header declares.
//
// The ranges are sorted by lower bound and disjoint, so the covering
// range is unique and a binary search finds it.
func IncbOf(cp uint32) Incb {
	lo, hi := 0, len(incbRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := incbRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return entry.class
		}
	}
	return IncbNone
}

// GraphemePublishedRowCount is how many data rows the pinned corpus
// carries, counted from the canonical GraphemeBreakTest.txt at
// generation. The corpus gate asserts the rows it reads from the
// vendored copy against this, so a row lost between the two fails
// rather than quietly shrinking the denominator.
const GraphemePublishedRowCount = 766
